package com.pringlestars.livesubtitle;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.hardware.display.*;import android.media.*;import android.media.projection.*;import android.view.*;import android.widget.*;import com.google.mlkit.vision.common.InputImage;import com.google.mlkit.vision.text.*;import com.google.mlkit.vision.text.latin.TextRecognizerOptions;import com.google.mlkit.nl.translate.*;import java.util.*;
public class CaptureService extends Service{
 Handler h=new Handler(Looper.getMainLooper()); MediaProjection mp; VirtualDisplay vd; ImageReader reader; WindowManager wm; TextView label; TextRecognizer ocr; Translator translator; boolean busy,ready,dead; int width,height,x,y,cw,ch,interval; long last,seen; String previous=""; LinkedHashMap<String,String> cache=new LinkedHashMap<String,String>(128,.75f,true){protected boolean removeEldestEntry(Map.Entry<String,String> e){return size()>128;}};
 BroadcastReceiver off=new BroadcastReceiver(){public void onReceive(Context c,Intent i){stopSelf();}};
 public IBinder onBind(Intent i){return null;}
 public int onStartCommand(Intent i,int flags,int id){if(i==null||mp!=null)return START_NOT_STICKY;if("stop".equals(i.getAction())){stopSelf();return START_NOT_STICKY;}
 NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("capture","자막 번역",NotificationManager.IMPORTANCE_LOW));PendingIntent stop=PendingIntent.getService(this,1,new Intent(this,CaptureService.class).setAction("stop"),PendingIntent.FLAG_IMMUTABLE);startForeground(1,new Notification.Builder(this,"capture").setSmallIcon(android.R.drawable.ic_menu_view).setContentTitle("실시간 자막 번역").addAction(new Notification.Action.Builder(null,"중지",stop).build()).build());
 try{registerReceiver(off,new IntentFilter(Intent.ACTION_SCREEN_OFF));wm=getSystemService(WindowManager.class);android.util.DisplayMetrics m=new android.util.DisplayMetrics();wm.getDefaultDisplay().getRealMetrics(m);width=m.widthPixels;height=m.heightPixels;android.content.SharedPreferences p=getSharedPreferences("settings",0);x=Math.min(width-1,width*p.getInt("x",5)/100);y=Math.min(height-1,height*p.getInt("y",60)/100);cw=Math.max(1,Math.min(width-x,width*p.getInt("w",90)/100));ch=Math.max(1,Math.min(height-y,height*p.getInt("h",15)/100));interval=p.getInt("interval",500);
 label=new TextView(this);label.setTextColor(-1);label.setTextSize(p.getInt("size",20));label.setGravity(Gravity.CENTER);label.setPadding(12,8,12,8);label.setBackgroundColor(0x99000000);WindowManager.LayoutParams lp=new WindowManager.LayoutParams(cw,-2,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);lp.gravity=Gravity.TOP|Gravity.LEFT;lp.x=x;lp.y=y+ch<height-100?y+ch:Math.max(0,y-120);lp.alpha=.8f;wm.addView(label,lp);label.setVisibility(View.INVISIBLE);
 ocr=TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);translator=Translation.getClient(new TranslatorOptions.Builder().setSourceLanguage(TranslateLanguage.ENGLISH).setTargetLanguage(TranslateLanguage.KOREAN).build());translator.downloadModelIfNeeded().addOnSuccessListener(v->ready=true).addOnFailureListener(e->{Toast.makeText(this,"번역 모델 다운로드 실패",Toast.LENGTH_LONG).show();stopSelf();});
 mp=getSystemService(MediaProjectionManager.class).getMediaProjection(i.getIntExtra("code",0),(Intent)i.getParcelableExtra("data"));mp.registerCallback(new MediaProjection.Callback(){public void onStop(){stopSelf();}public void onCapturedContentResize(int w,int hh){if(w!=width||hh!=height)stopSelf();}},h);reader=ImageReader.newInstance(width,height,PixelFormat.RGBA_8888,2);vd=mp.createVirtualDisplay("subtitle",width,height,m.densityDpi,DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,reader.getSurface(),null,h);reader.setOnImageAvailableListener(r->frame(r),h);
 }catch(Exception e){stopSelf();}return START_NOT_STICKY;}
 void frame(ImageReader r){if(dead)return;try(Image im=r.acquireLatestImage()){if(im==null)return;long now=SystemClock.elapsedRealtime();if(!ready||busy||now-last<interval)return;last=now;Image.Plane p=im.getPlanes()[0];int stride=p.getRowStride()/p.getPixelStride();Bitmap full=Bitmap.createBitmap(stride,height,Bitmap.Config.ARGB_8888);full.copyPixelsFromBuffer(p.getBuffer());Bitmap crop=Bitmap.createBitmap(full,x,y,cw,ch);if(crop!=full)full.recycle();busy=true;ocr.process(InputImage.fromBitmap(crop,0)).addOnCompleteListener(t->{crop.recycle();if(dead)return;if(!t.isSuccessful()){busy=false;return;}String text=t.getResult().getText().replaceAll("\\s+"," ").trim();if(text.isEmpty()){if(SystemClock.elapsedRealtime()-seen>1500){label.setVisibility(View.INVISIBLE);previous="";}busy=false;return;}seen=SystemClock.elapsedRealtime();if(text.equals(previous)){busy=false;return;}if(cache.containsKey(text)){show(text,cache.get(text));busy=false;return;}translator.translate(text).addOnCompleteListener(a->{if(!dead&&a.isSuccessful()){cache.put(text,a.getResult());show(text,a.getResult());}busy=false;});});}catch(Exception e){busy=false;}}
 void show(String source,String translated){previous=source;label.setText(translated);label.setVisibility(View.VISIBLE);}
 public void onDestroy(){dead=true;try{unregisterReceiver(off);}catch(Exception e){}if(vd!=null)vd.release();if(reader!=null)reader.close();if(mp!=null)mp.stop();if(label!=null&&wm!=null)wm.removeView(label);if(ocr!=null)ocr.close();if(translator!=null)translator.close();super.onDestroy();}
}